pageCss:
.subpage-hero {
  background: linear-gradient(135deg, var(--navy-dark) 0%, #1B3A5C 100%);
  padding: 160px 48px 80px;
  text-align: center;
}
.subpage-hero .section-label { color: rgba(255,255,255,0.5); }
.subpage-hero h1 {
  font-size: clamp(30px, 5vw, 50px);
  font-weight: 900;
  color: var(--white);
  letter-spacing: -0.03em;
  line-height: 1.1;
  margin-bottom: 20px;
  max-width: 880px;
  margin-left: auto;
  margin-right: auto;
}
.subpage-hero p {
  font-size: 17px;
  color: rgba(255,255,255,0.65);
  max-width: 640px;
  margin: 0 auto 16px;
  line-height: 1.65;
}
.subpage-hero p strong { color: var(--white); font-weight: 700; }
.hero-ctas {
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  gap: 12px;
  margin: 32px auto 8px;
}
.hero-download {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  background: var(--red);
  color: var(--white);
  padding: 14px 28px;
  border-radius: var(--radius);
  font-size: 15px;
  font-weight: 700;
  transition: background 0.2s;
}
.hero-download:hover { background: var(--red-light); }
.hero-secondary {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  border: 1px solid rgba(255,255,255,0.35);
  color: var(--white);
  padding: 14px 28px;
  border-radius: var(--radius);
  font-size: 15px;
  font-weight: 700;
  transition: background 0.2s, border-color 0.2s;
}
.hero-secondary:hover { background: rgba(255,255,255,0.1); border-color: rgba(255,255,255,0.6); }

.paper-body {
  background: var(--white);
  padding: 72px 48px 104px;
}
.paper-inner {
  max-width: 780px;
  margin: 0 auto;
}

.release-meta {
  display: flex;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
  margin-bottom: 32px;
  padding-bottom: 28px;
  border-bottom: 1px solid var(--gray-200);
}
.release-badge {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  background: var(--navy-dark);
  color: var(--white);
  padding: 5px 12px;
  border-radius: 4px;
}
.release-date { font-size: 14px; color: var(--gray-400); }
.release-author { font-size: 14px; font-weight: 700; color: var(--navy); }

.paper-provenance {
  font-size: 14.5px;
  font-style: italic;
  color: var(--gray-400);
  line-height: 1.75;
  margin-bottom: 40px;
  padding-left: 18px;
  border-left: 3px solid var(--gray-200);
}
.paper-provenance a { color: var(--gray-400); text-decoration: underline; }
.paper-provenance a:hover { color: var(--red); }

.paper-toc {
  background: var(--cream);
  border-radius: var(--radius-lg);
  padding: 24px 28px;
  margin-bottom: 8px;
}
.paper-toc-label {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--navy);
  margin-bottom: 14px;
}
.paper-toc ol {
  list-style: none;
  margin: 0;
  padding: 0;
  columns: 2;
  column-gap: 32px;
}
.paper-toc li {
  font-size: 14.5px;
  line-height: 1.6;
  margin-bottom: 8px;
  break-inside: avoid;
}
.paper-toc a { color: var(--navy-dark); }
.paper-toc a:hover { color: var(--red); text-decoration: underline; }

.paper-inner h2 {
  font-size: clamp(20px, 3vw, 26px);
  font-weight: 800;
  color: var(--navy-dark);
  letter-spacing: -0.02em;
  margin: 56px 0 20px;
  padding-top: 10px;
  border-top: 3px solid var(--red);
  scroll-margin-top: 100px;
}
.paper-inner h3 {
  font-size: 17px;
  font-weight: 700;
  color: var(--navy-dark);
  margin: 32px 0 12px;
}
.paper-inner p {
  font-size: 16px;
  color: var(--gray-600);
  line-height: 1.8;
  margin-bottom: 16px;
}
.paper-inner p a { color: var(--navy); text-decoration: underline; }
.paper-inner p a:hover { color: var(--red); }
.paper-inner ul {
  list-style: none;
  margin: 0 0 20px;
  padding: 0;
}
.paper-inner ul li {
  font-size: 16px;
  color: var(--gray-600);
  line-height: 1.75;
  padding: 6px 0 6px 24px;
  position: relative;
}
.paper-inner ul li::before {
  content: '';
  position: absolute;
  left: 4px;
  top: 15px;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--red);
}

blockquote {
  margin: 24px 0 32px;
  padding: 24px 32px;
  background: var(--cream);
  border-radius: var(--radius-lg);
  border-left: 4px solid var(--navy);
}
blockquote p {
  font-size: 16.5px;
  font-style: italic;
  color: var(--navy-dark);
  line-height: 1.7;
  margin-bottom: 8px !important;
}
blockquote p:last-of-type { margin-bottom: 8px !important; }
blockquote cite {
  font-size: 13px;
  font-style: normal;
  font-weight: 600;
  color: var(--gray-400);
}
blockquote cite a { color: var(--gray-400); text-decoration: underline; }
blockquote cite a:hover { color: var(--red); }
blockquote .quote-source {
  display: block;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--red);
  font-style: normal;
  margin-bottom: 10px;
}

.scope-box {
  background: var(--cream);
  border: 2px solid var(--navy);
  border-radius: var(--radius-lg);
  padding: 32px 36px;
  margin: 32px 0;
  box-shadow: 0 4px 20px rgba(27,47,78,0.08);
}
.scope-box-label {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--navy);
  margin-bottom: 14px;
  display: flex;
  align-items: center;
  gap: 10px;
}
.scope-box-label::after {
  content: '';
  flex: 1;
  height: 1px;
  background: rgba(27,47,78,0.2);
}
.scope-box p {
  margin-bottom: 14px !important;
  font-size: 16px !important;
  color: var(--navy-dark) !important;
  line-height: 1.75 !important;
}
.scope-box p:last-child { margin-bottom: 0 !important; }

.finding-box {
  background: var(--navy-dark);
  border-radius: var(--radius-lg);
  padding: 28px 32px;
  margin: 32px 0;
}
.finding-box h3 {
  font-size: 12px !important;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.55) !important;
  margin: 0 0 12px !important;
}
.finding-box p {
  font-size: 18px !important;
  font-weight: 600;
  color: var(--white) !important;
  line-height: 1.6 !important;
  margin: 0 !important;
}

.defs-table-wrap {
  overflow-x: auto;
  margin: 24px 0 32px;
  border-radius: var(--radius);
  border: 1px solid var(--gray-200);
}
.defs-table {
  width: 100%;
  border-collapse: collapse;
  background: var(--white);
  font-size: 14.5px;
}
.defs-table th {
  background: var(--navy-dark);
  color: var(--white);
  text-align: left;
  padding: 12px 16px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  white-space: nowrap;
}
.defs-table td {
  padding: 14px 16px;
  border-top: 1px solid var(--gray-200);
  color: var(--gray-600);
  line-height: 1.6;
  vertical-align: top;
}
.defs-table td:first-child { font-weight: 700; color: var(--navy-dark); white-space: nowrap; }

.draft-def {
  background: var(--cream);
  border-left: 4px solid var(--navy);
  border-radius: var(--radius);
  padding: 24px 28px;
  margin: 20px 0;
}
.draft-def p { font-size: 15.5px !important; color: var(--navy-dark) !important; line-height: 1.75 !important; }
.draft-def p:last-child { margin-bottom: 0 !important; }
.draft-def .def-term { font-weight: 800; }

.sources-list p {
  font-size: 15px !important;
  line-height: 1.75 !important;
}
.sources-list strong { color: var(--navy-dark); }

.related-cta {
  background: var(--cream);
  border-radius: var(--radius-lg);
  padding: 32px 36px;
  margin-top: 56px;
  text-align: center;
}
.related-cta h3 { margin-top: 0 !important; }
.related-cta p { margin-bottom: 20px; }
.related-cta .btn-file {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--navy-dark);
  color: var(--white);
  padding: 12px 24px;
  border-radius: var(--radius);
  font-size: 14.5px;
  font-weight: 700;
  margin: 4px;
  transition: background 0.2s;
}
.related-cta .btn-file:hover { background: var(--red); }

@media (max-width: 600px) {
  .subpage-hero { padding: 140px 24px 64px; }
  .paper-body { padding: 56px 24px 80px; }
  .paper-toc ol { columns: 1; }
  .scope-box { padding: 24px 22px; }
  blockquote { padding: 20px 22px; }
  .release-meta { flex-direction: column; align-items: flex-start; gap: 10px; }
}
